const payload = $input.first().json;
const data = payload.data || payload;

const urgencyEmoji = {
  'critical': '🔴 CRITICAL',
  'low': '🟠 LOW',
  'warning': '🟡 WARNING'
}[data.urgency] || '⚠️';

return [{
  json: {
    subject: `${urgencyEmoji} – Low Stock: ${data.medicineName} at ${data.pharmacyName}`,
    body: `Low inventory alert from MediFind.\n\n` +
          `Medicine: ${data.medicineName}\n` +
          `Pharmacy: ${data.pharmacyName} (ID: ${data.pharmacyId})\n` +
          `Current Stock: ${data.currentStock} units\n` +
          `Threshold: ${data.threshold} units\n` +
          `Urgency: ${data.urgency?.toUpperCase() || 'WARNING'}\n\n` +
          `⚡ Please restock this medicine immediately to avoid service disruption.\n\n` +
          `Triggered at: ${payload.timestamp}`,
    urgency: data.urgency,
    medicineName: data.medicineName,
    pharmacyName: data.pharmacyName,
    currentStock: data.currentStock,
    isCritical: data.urgency === 'critical'
  }
}];
